enum ConnectionState {
    Disconnected,
    Connecting { initiated: SystemTime },
    Connected { session_id: String },
}

let summary = match state {
    ConnectionState::Disconnected => "down".to_owned(),
    ConnectionState::Connecting { initiated } => format!("connecting since {initiated:?}"),
    ConnectionState::Connected { session_id } => session_id,  // no wildcard arm
};
